{
    if(size < 2) return 0;

    int flags = data[0];
    int fmt = data[1] & 0x7F;
    int stream = data[1] >> 7;

    data+=2; size-=2;

    int ret;
    unsigned char *out = NULL;

    spng_ctx *ctx = spng_ctx_new(0);
